<?php require dirname(__DIR__).'/app/bootstrap.php';
if(current_user()){header('Location: '.path('admin/index.php'));exit;}
$error='';if(!empty($_SESSION['pending_mfa_started'])&&time()-(int)$_SESSION['pending_mfa_started']>600){unset($_SESSION['pending_mfa_user'],$_SESSION['pending_mfa_started']);}$awaiting=!empty($_SESSION['pending_mfa_user']);
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_verify();
 if(($_POST['action']??'')==='verify_mfa'&&$awaiting){
  $u=query_one('SELECT * FROM users WHERE id=? AND active=1',[(int)$_SESSION['pending_mfa_user']]);$code=strtoupper(preg_replace('/[^A-Z0-9]/','',(string)($_POST['code']??'')));$fingerprint=hash('sha256',(string)($u['id']??0).'|'.($_SERVER['REMOTE_ADDR']??''));$window=db_is_sqlite()?"datetime('now','-15 minutes')":'DATE_SUB(NOW(),INTERVAL 15 MINUTE)';$attempts=$u?query_one('SELECT COUNT(*) AS n FROM mfa_attempts WHERE user_id=? AND identifier_hash=? AND attempted_at>'.$window,[(int)$u['id'],$fingerprint]):['n'=>0];
  if((int)($attempts['n']??0)>=8){http_response_code(429);$error='MFA yafunzwe by’agateganyo. Ongera ugerageze nyuma y’iminota 15.';}else{
   try{$secret=$u?Security::decrypt((string)$u['mfa_secret_encrypted'],encryption_keys()):'';}catch(Throwable){$secret='';}$valid=$u&&Security::verifyTotp($secret,$code);$recoveryId=0;
   if($u&&!$valid&&strlen($code)===12){foreach(query_all('SELECT id,code_hash FROM mfa_recovery_codes WHERE user_id=? AND used_at IS NULL',[(int)$u['id']]) as $recovery){if(password_verify($code,$recovery['code_hash'])){$valid=true;$recoveryId=(int)$recovery['id'];break;}}}
   if(!$valid){if($u)db()->prepare('INSERT INTO mfa_attempts(user_id,identifier_hash) VALUES (?,?)')->execute([(int)$u['id'],$fingerprint]);$error='Kode ya MFA cyangwa recovery code ntiyemewe.';audit_log('mfa_failed','user',(int)($u['id']??0));}else{
    db()->beginTransaction();try{if($recoveryId){$s=db()->prepare('UPDATE mfa_recovery_codes SET used_at='.sql_now().' WHERE id=? AND used_at IS NULL');$s->execute([$recoveryId]);if($s->rowCount()!==1)throw new RuntimeException('Recovery code was already used.');}db()->prepare('DELETE FROM mfa_attempts WHERE user_id=?')->execute([(int)$u['id']]);db()->commit();}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();throw $e;}
    session_regenerate_id(true);$roles=load_user_roles((int)$u['id'],(string)$u['role']);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role'],'roles'=>$roles,'session_version'=>(int)$u['session_version'],'mfa_enabled'=>true,'mfa_required'=>(bool)$u['mfa_required']];unset($_SESSION['pending_mfa_user'],$_SESSION['pending_mfa_started']);$_SESSION['last_activity']=$_SESSION['session_started_at']=time();db()->prepare('UPDATE users SET last_login_at='.sql_now().' WHERE id=?')->execute([(int)$u['id']]);audit_log($recoveryId?'login_mfa_recovery':'login_mfa','user',(int)$u['id']);header('Location: '.path('admin/index.php'));exit;
   }
  }
 }else{$email=strtolower(trim((string)($_POST['email']??'')));$pw=(string)($_POST['password']??'');$key=hash('sha256',$email.'|'.($_SERVER['REMOTE_ADDR']??''));$window=db_is_sqlite()?"datetime('now','-15 minutes')":'DATE_SUB(NOW(),INTERVAL 15 MINUTE)';$count=query_one('SELECT COUNT(*) AS n FROM login_attempts WHERE identifier_hash=? AND attempted_at>'.$window,[$key]);
  if((int)($count['n']??0)>=8){http_response_code(429);$error='Wagerageje inshuro nyinshi. Subira nyuma y’iminota 15.';}else{
   $u=query_one('SELECT * FROM users WHERE email=? AND active=1',[$email]);
   if(!$u||!password_verify($pw,$u['password_hash'])){db()->prepare('INSERT INTO login_attempts(identifier_hash) VALUES (?)')->execute([$key]);audit_log('password_login_failed','user',(int)($u['id']??0));$error='Email cyangwa password ntabwo bihuye.';}
   else{if(password_needs_rehash($u['password_hash'],PASSWORD_DEFAULT)){$newHash=password_hash($pw,PASSWORD_DEFAULT);db()->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([$newHash,(int)$u['id']]);$u['password_hash']=$newHash;}
    if(!empty($u['mfa_enabled'])){$_SESSION['pending_mfa_user']=(int)$u['id'];$_SESSION['pending_mfa_started']=time();$awaiting=true;db()->prepare('DELETE FROM login_attempts WHERE identifier_hash=?')->execute([$key]);}
    else{session_regenerate_id(true);$roles=load_user_roles((int)$u['id'],(string)$u['role']);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['full_name'],'email'=>$u['email'],'role'=>$u['role'],'roles'=>$roles,'session_version'=>(int)$u['session_version'],'mfa_enabled'=>false,'mfa_required'=>(bool)$u['mfa_required']];$_SESSION['last_activity']=$_SESSION['session_started_at']=time();db()->prepare('UPDATE users SET last_login_at='.sql_now().' WHERE id=?')->execute([(int)$u['id']]);db()->prepare('DELETE FROM login_attempts WHERE identifier_hash=?')->execute([$key]);audit_log('login','user',(int)$u['id']);header('Location: '.path('admin/index.php'));exit;}
   }
  }
 }
}
?><!doctype html><html lang="rw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Newsroom Login · AFRIVOX NEWS</title><link rel="stylesheet" href="<?=e(path('assets/style.css'))?>"><link rel="stylesheet" href="<?=e(path('assets/admin.css'))?>"></head><body class="login-page"><main class="login-panel"><div class="overline">EDITORIAL WORKSPACE · SECURE ACCESS</div><a class="login-brand" href="<?=e(path())?>">AFRIVOX NEWS<span>.</span></a><h1>Welcome to<br><em>the newsroom.</em></h1><?php if($error):?><div class="form-error"><?=e($error)?></div><?php endif;?><?php if($awaiting):?><p>Injiza kode y’imibare 6 iri muri authenticator cyangwa recovery code wabikiye ahizewe.</p><form method="post" class="public-form"><?=csrf_field()?><input type="hidden" name="action" value="verify_mfa"><label>MFA / RECOVERY CODE<input name="code" minlength="6" maxlength="14" autocomplete="one-time-code" required autofocus></label><button type="submit">EMEZA MFA →</button></form><?php else:?><p>Kwinjira byemewe ku banyamakuru n'abakozi babifitiye uburenganzira gusa.</p><form method="post" class="public-form"><?=csrf_field()?><label>Email<input type="email" name="email" required autocomplete="username"></label><label>Password<input type="password" name="password" required autocomplete="current-password"></label><button type="submit">INJIRA MU NEWSROOM →</button></form><a href="<?=e(path('admin/forgot-password.php'))?>">Forgot password?</a><?php endif;?><a class="return-link" href="<?=e(path())?>">← SUBIRA KU KINYAMAKURU</a></main></body></html>
